export type HealthcareLegalEntityCopy = { [Key in keyof typeof rows]: string };
export function getRegistryCopy(
  base: Pick<HealthcareLegalEntityCopy, "registrySourceTime" | "registryReference" | "ico">,
  countryCode: string | null | undefined,
) {
  const country = countryCode === "CZ" || countryCode === "RO" ? countryCode : "SK";
  return {
    countryCode: country,
    sourceLabel: country === "CZ" ? "ARES" : country === "RO" ? "ANAF" : "OR SR",
    sourceCode: country === "CZ" ? "ARES" : country === "RO" ? "ANAF" : "ORSR",
    sourceTimeLabel: base.registrySourceTime,
    referenceLabel: country === "SK" ? "OR SR" : base.registryReference,
    identifierLabel: country === "RO" ? "CUI" : base.ico,
  };
}
export function withRegistryCopy(base: HealthcareLegalEntityCopy, countryCode: string | null | undefined): HealthcareLegalEntityCopy {
  if (countryCode !== "CZ" && countryCode !== "RO") return base;
  const registry = getRegistryCopy(base, countryCode);
  const replace = (value: string) => value
    .replace(/OR[\s-]*SR/gi, registry.sourceLabel)
    .replace(/IČO/gi, registry.identifierLabel);
  const copy = Object.fromEntries(Object.entries(base).map(([key, value]) => [key, replace(value)])) as HealthcareLegalEntityCopy;
  return {
    ...copy,
    recordSource: `${base.registrySourceDescription} · ${registry.sourceLabel}`,
    emptyHint: base.verifyIdentifierHint,
    search: base.search.replace(/IČO/gi, registry.identifierLabel),
    verify: base.verify.replace(/IČO/gi, registry.identifierLabel),
    verificationHint: `${base.verificationSourceHint} · ${registry.sourceLabel}`,
    siteComparisonNotice: `${base.siteComparisonSourceNotice} · ${registry.sourceLabel}`,
    orsrSyncAt: base.registrySourceTime,
    fetchCompleteData: base.fetchSourceData,
    completeDataSaved: `${base.sourceDataSaved} · ${registry.sourceLabel}`,
  };
}
export const healthcareLegalEntityTranslations = Object.fromEntries(
  languages.map((locale, index) => [locale, Object.fromEntries(Object.entries(rows).map(([key, values]) => [key, values[index]]))]),
) as Record<Locale, HealthcareLegalEntityCopy>;
